#!/usr/bin/env node
// Generates packages/shared/src from the exported JSON Schemas in schemas/.
//   node scripts/gen-types.mjs           write the generated files
//   node scripts/gen-types.mjs --check   exit 1 if the committed files are out of date
import { readdir, readFile, writeFile, mkdir, rm } from "node:fs/promises";
import { isDeepStrictEqual } from "node:util";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { compile } from "json-schema-to-typescript";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const schemasDir = path.join(root, "schemas");
const outDir = path.join(root, "packages", "shared", "src");
const check = process.argv.includes("--check");

const BANNER = `/* eslint-disable */
// GENERATED by \`make gen\` from services/api/app/schemas (Pydantic). Do not edit by hand.
`;

async function loadSchemas() {
  const files = (await readdir(schemasDir)).filter((f) => f.endsWith(".json")).sort();
  if (files.length === 0) throw new Error(`no schemas in ${schemasDir}; run make gen`);
  return Promise.all(
    files.map(async (file) => ({
      file,
      text: await readFile(path.join(schemasDir, file), "utf8"),
    })),
  );
}

/** Drop titles below the definition level so the generator names types after definitions only. */
function stripNestedTitles(node, isDefinition = false) {
  if (Array.isArray(node)) return node.map((n) => stripNestedTitles(n));
  if (node === null || typeof node !== "object") return node;
  const out = {};
  for (const [key, value] of Object.entries(node)) {
    if (key === "title" && !isDefinition) continue;
    out[key] =
      key === "properties"
        ? Object.fromEntries(Object.entries(value).map(([k, v]) => [k, stripNestedTitles(v)]))
        : stripNestedTitles(value);
  }
  return out;
}

/** Merge every schema's $defs, plus each schema itself, into one set of definitions. */
function mergeDefinitions(schemas) {
  const defs = {};
  const add = (name, def, source) => {
    if (name in defs && !isDeepStrictEqual(defs[name], def)) {
      throw new Error(
        `schema definition "${name}" differs between files (seen again in ${source})`,
      );
    }
    defs[name] = def;
  };
  for (const { file, text } of schemas) {
    const { $defs = {}, $schema: _ignored, ...top } = JSON.parse(text);
    for (const [name, def] of Object.entries($defs)) add(name, stripNestedTitles(def, true), file);
    add(top.title, stripNestedTitles(top, true), file);
  }
  return defs;
}

async function render(schemas) {
  const defs = mergeDefinitions(schemas);
  const names = Object.keys(defs).sort();
  const wrapper = {
    title: "SharedSchemas",
    type: "object",
    additionalProperties: false,
    properties: Object.fromEntries(names.map((n) => [n, { $ref: `#/$defs/${n}` }])),
    $defs: Object.fromEntries(names.map((n) => [n, defs[n]])),
  };
  let types = await compile(wrapper, "SharedSchemas", {
    bannerComment: BANNER,
    additionalProperties: false,
    declareExternallyReferenced: true,
    strictIndexSignatures: true,
    ignoreMinAndMaxItems: true,
    style: { singleQuote: false, printWidth: 100 },
  });
  // The wrapper only exists to pull every definition in; drop its own interface.
  types = types.replace(/export interface SharedSchemas \{[\s\S]*?\n\}\n/, "");

  const files = new Map();
  files.set("types.ts", types);
  for (const { file, text } of schemas) files.set(path.posix.join("schemas", file), text);
  files.set("index.ts", `${BANNER}export type * from "./types";\n`);
  return files;
}

async function listFiles(dir, prefix = "") {
  let entries;
  try {
    entries = await readdir(dir, { withFileTypes: true });
  } catch {
    return [];
  }
  const out = [];
  for (const entry of entries) {
    const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
    if (entry.isDirectory()) out.push(...(await listFiles(path.join(dir, entry.name), rel)));
    else out.push(rel);
  }
  return out;
}

const files = await render(await loadSchemas());

if (check) {
  const problems = [];
  for (const [rel, content] of files) {
    let current = null;
    try {
      current = (await readFile(path.join(outDir, rel), "utf8")).replace(/\r\n/g, "\n");
    } catch {
      /* missing */
    }
    if (current !== content) problems.push(`out of date: packages/shared/src/${rel}`);
  }
  for (const rel of await listFiles(outDir)) {
    if (!files.has(rel)) problems.push(`unexpected: packages/shared/src/${rel}`);
  }
  if (problems.length) {
    console.error(problems.join("\n"));
    console.error("Generated TypeScript is out of date. Run `make gen` and commit the result.");
    process.exit(1);
  }
  console.log("packages/shared is up to date");
} else {
  await rm(outDir, { recursive: true, force: true });
  for (const [rel, content] of files) {
    const target = path.join(outDir, rel);
    await mkdir(path.dirname(target), { recursive: true });
    await writeFile(target, content, "utf8");
  }
  console.log(`wrote ${files.size} files to packages/shared/src`);
}
